#!/usr/bin/env bash
# Every repository-gate fixture, fed to the generated scripts beside this file.
# `relearn check` ran the same records through the Rust judge; this runs them
# through the generated `awk` judge. With `--trees <dir>`, it also builds a
# checkout per gate from <dir>/<name>/hit and <dir>/<name>/clean, runs
# `git init` and `git add`, and runs the whole gate, collect stage included.
# A tree stores a dotfile as `dot-<name>`, so the repository committing the
# tree never reads its `.gitattributes` or `.gitignore`.
# Generated by relearn; edit the rule files, never this script.
set -uo pipefail
export LC_ALL=C

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
trees=""
case "${1:-}" in
  --trees) trees="${2:-}"; [ -d "$trees" ] || { echo "FAIL: --trees needs a directory"; exit 1; } ;;
  "") ;;
  *) echo "usage: test-gates.sh [--trees <dir>]"; exit 2 ;;
esac
if [ -n "$trees" ] && ! command -v git >/dev/null 2>&1; then
  echo "DISARMED (exit 2, not a pass): git is not on PATH, so no tree ran"
  exit 2
fi
work="$(mktemp -d)" || { echo "FAIL: no scratch directory"; exit 1; }
trap 'rm -rf "$work"' EXIT
pass=0
failed=0

# judge_case <script> <expect hit|clean> [record...]
judge_case() {
  local script="$1" expect="$2"
  shift 2
  printf '%s\n' "$@" | bash "$here/$script" --judge > /dev/null 2> "$work/stderr"
  local got=$? want=0
  [ "$expect" = hit ] && want=1
  if [ "$got" -eq "$want" ]; then
    pass=$((pass + 1))
  else
    failed=$((failed + 1))
    printf 'FAIL  %s  records expected %s: judge exit %s, stderr %s bytes\n' \
      "$script" "$expect" "$got" "$(wc -c < "$work/stderr" | tr -d ' ')"
  fi
}

# tree_case <script> <gate name> <expect hit|clean> <action block|warn>
tree_case() {
  local script="$1" gate="$2" expect="$3" action="$4"
  local src="$trees/$gate/$expect"
  if [ ! -d "$src" ]; then
    failed=$((failed + 1))
    printf 'FAIL  %s  no %s tree at %s\n' "$script" "$expect" "$src"
    return
  fi
  local repo="$work/tree-$gate-$expect"
  mkdir -p "$repo" && cp -R "$src/." "$repo/"
  local f
  find "$repo" -name 'dot-*' > "$work/dots"
  while IFS= read -r f; do
    mv "$f" "$(dirname "$f")/.$(basename "$f" | sed 's/^dot-//')"
  done < "$work/dots"
  git -C "$repo" init -q > /dev/null 2>&1 && git -C "$repo" add -A > /dev/null 2>&1 || {
    failed=$((failed + 1))
    printf 'FAIL  %s  git could not stage the %s tree\n' "$script" "$expect"
    return
  }
  local out got ok=no
  out="$(bash "$here/$script" "$repo" 2> "$work/stderr")"
  got=$?
  case "$expect:$action" in
    clean:*) [ "$got" -eq 0 ] && [ -z "$out" ] && ok=yes ;;
    hit:block) [ "$got" -eq 1 ] && case "$out" in *BLOCKED*) true ;; *) false ;; esac && ok=yes ;;
    hit:warn) [ "$got" -eq 0 ] && case "$out" in *WARNING*) true ;; *) false ;; esac && ok=yes ;;
  esac
  if [ "$ok" = yes ]; then
    pass=$((pass + 1))
  else
    failed=$((failed + 1))
    printf 'FAIL  %s  %s tree expected %s (%s): exit %s, stdout %s bytes, stderr %s bytes\n' \
      "$script" "$gate" "$expect" "$action" "$got" "${#out}" "$(wc -c < "$work/stderr" | tr -d ' ')"
  fi
}

# executable-text-eol-pinned
judge_case 'executable-text-eol-pinned.sh' hit $'scripts/deploy.sh\t#!/usr/bin/env bash\tunspecified\tunspecified'
judge_case 'executable-text-eol-pinned.sh' hit $'tools/run\t#!/bin/sh\tset\tcrlf'
judge_case 'executable-text-eol-pinned.sh' clean $'scripts/deploy.sh\t#!/usr/bin/env bash\tset\tlf' $'README.md\t# A project\tunspecified\tunspecified'
judge_case 'executable-text-eol-pinned.sh' clean $'bin/tool\t#!/bin/sh\tunset\tunspecified'
if [ -n "$trees" ]; then
  tree_case 'executable-text-eol-pinned.sh' 'executable-text-eol-pinned' hit block
  tree_case 'executable-text-eol-pinned.sh' 'executable-text-eol-pinned' clean block
fi
# five-root-documents
judge_case 'five-root-documents.sh' hit $'README.md' $'CLAUDE.md' $'ARCHITECTURE.md' $'FEATURES.md' $'TODO.md' $'NOTES.md'
judge_case 'five-root-documents.sh' hit $'README.md' $'DESIGN.md' $'src/main.rs'
judge_case 'five-root-documents.sh' clean $'README.md' $'CLAUDE.md' $'ARCHITECTURE.md' $'FEATURES.md' $'TODO.md' $'AGENTS.md' $'docs/guide.md' $'Cargo.toml'
judge_case 'five-root-documents.sh' clean $'src/lib.rs' $'docs/NOTES.md'
if [ -n "$trees" ]; then
  tree_case 'five-root-documents.sh' 'five-root-documents' hit warn
  tree_case 'five-root-documents.sh' 'five-root-documents' clean warn
fi
# pass-by-value-lint-on
judge_case 'pass-by-value-lint-on.sh' hit $'Cargo.toml\tunsafe_code\tforbid'
judge_case 'pass-by-value-lint-on.sh' hit $'Cargo.toml\tclippy::pedantic\twarn' $'src/lib.rs\tclippy::needless_pass_by_value\tallow'
judge_case 'pass-by-value-lint-on.sh' clean $'Cargo.toml\tclippy::pedantic\twarn'
judge_case 'pass-by-value-lint-on.sh' clean $'src/main.rs\tclippy::needless_pass_by_value\tdeny'
if [ -n "$trees" ]; then
  tree_case 'pass-by-value-lint-on.sh' 'pass-by-value-lint-on' hit block
  tree_case 'pass-by-value-lint-on.sh' 'pass-by-value-lint-on' clean block
fi

if [ "$failed" -eq 0 ]; then
  echo "PASS: $pass gate case(s) agree with the generated scripts"
  exit 0
fi
echo "FAIL: $failed of $((pass + failed)) gate case(s) disagree with the generated scripts"
exit 1

